import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import {connect} from "react-redux";
import TaskCard from "./TaskCard/TaskCard";
import {changeTaskOrder} from "../../store/actions/task.actions";

const TaskList = ({tasks, changeTaskOrder}) => {

    const handleDragEnd = (result) => {
        console.log(result);
        if (!result.destination) return;
        // Reorder logic here
        changeTaskOrder(result.draggableId, result.destination.index);
    };

    return (
        <DragDropContext onDragEnd={handleDragEnd}>
            <Droppable droppableId="tasks">
                {(provided) => (
                    <div {...provided.droppableProps} ref={provided.innerRef}>
                        {tasks.map((task, index) => (
                            <Draggable
                                key={task.id}
                                draggableId={task.id.toString()}
                                index={index}
                            >
                                {(provided) => (
                                    <div
                                        ref={provided.innerRef}
                                        {...provided.draggableProps}
                                        {...provided.dragHandleProps}
                                    >
                                        <TaskCard
                                            task={task}
                                            dragHandleProps={provided.dragHandleProps}

                                        />
                                    </div>
                                )}
                            </Draggable>
                        ))}
                        {provided.placeholder}
                    </div>
                )}
            </Droppable>
        </DragDropContext>
    );
};

const mapStateToProps = state => ({
    tasks: state.tasks.tasks,
})

export default connect(mapStateToProps, {changeTaskOrder}) (TaskList);