import {ADD_TASK, CHANGE_TASK_ORDERS, DELETE_TASK, MAKE_TASK_COMPLETE} from "./types.actions";
import {v4 as uuid} from 'uuid';

export const makeTaskComplete = (id) => {
    return {
        type: MAKE_TASK_COMPLETE,
        id
    }
}

export const changeTaskOrder = (id, order) => {
    return {
        type: CHANGE_TASK_ORDERS,
        id: id,
        order
    }
}

export const deleteTask = id => {
    return {
        type: DELETE_TASK,
        id
    }
}

export const addTask = (task) => {
    const id = uuid();
    return {
        type: ADD_TASK,
        task,
        id
    }
}