import * as actionTypes from '../actions/types.actions';

const initialState = {
    tasks: [
        {
            name: "Get eggs",
            id: 1,
            complete: false
        },
        {
            name: "bring vegetables ",
            id: 2,
            complete: false
        }
    ]
}

export default (state = initialState, action) => {
    switch (action.type) {
        case actionTypes.MAKE_TASK_COMPLETE:
            return {
                ...state,
                tasks: state.tasks.map(task =>
                    task.id === action.id
                        ? { ...task, complete: !task.complete } // New object
                        : task
                )
            };
        case actionTypes.CHANGE_TASK_ORDERS:
            const tasksCopy = JSON.parse(JSON.stringify(state.tasks));
            const currentIndex = tasksCopy.findIndex(task => task.id == action.id);

            if(currentIndex === -1 || currentIndex == action.order) return;

            const [movedTask] = tasksCopy.splice(currentIndex, 1);
            console.log(movedTask);
            tasksCopy.splice(action.order, 0, movedTask);
            console.log(tasksCopy);
            return {
                ...state,
                tasks: tasksCopy
            }
        case actionTypes.DELETE_TASK:
            return {
                ...state,
                tasks: JSON.parse(JSON.stringify(state.tasks.filter(t => t.id != action.id)))
            }
        case actionTypes.ADD_TASK:
            return {
                ...state,
                tasks: JSON.parse(JSON.stringify([...state.tasks, { id: action.id, name: action.task, complete: false}]))
            }
        default:
            return state;
    }
}