import React from 'react';
import { MdDelete, MdCheckCircle, MdRadioButtonUnchecked } from 'react-icons/md';
import styles from './TaskCard.module.css'; // CSS Modules (or use Tailwind)
import {makeTaskComplete, changeTaskOrder, deleteTask} from "../../../store/actions/task.actions";
import {connect} from "react-redux";

const TaskCard = ({ task, dragHandleProps, deleteTask, changeTaskOrder, makeTaskComplete }) => {

    const handleDelete = () => {
        deleteTask(task.id);
    };

    const handleToggleComplete = e => {
        e.preventDefault();
        e.stopPropagation();
        makeTaskComplete(task.id);
    };

    return (
        <div className={`${styles.taskCard} ${task.complete ? styles.completed : ''}`}>
            {/* Checkbox to toggle completion */}
            <div className={styles.TaskCard__left}>
                <div onClick={handleToggleComplete} className={styles.toggleButton}>
                    {task.complete ? (
                        <i className="fa-regular fa-circle-check"></i>
                    ) : (
                        <i className="fa-regular fa-circle"></i>
                    )}
                </div>

                {/* Task text */}
                <span className={styles.taskText}>{task.name}</span>
            </div>

            <div className={styles.TaskCard__right}>
                {/* Delete button */}
                <div onClick={handleDelete} className={styles.deleteButton}>
                    <MdDelete />
                </div>

                {/* Drag handle (for react-beautiful-dnd) */}
                <div {...dragHandleProps} className={styles.dragHandle}>
                    ☰
                </div>
            </div>
        </div>
    );
};

export default connect(null, {deleteTask, changeTaskOrder, makeTaskComplete}) (TaskCard);